1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export type Step =
23	  | { op: "quote"; items: Item[] }
24	  | { op: "claim"; policy: number; incident: Incident };
25	
26	export interface Scenario {
27	  customer: Customer;
28	  steps: Step[];
29	}
30	
31	export type StepResult =
32	  | { premium: number }
33	  | { payout: number; remainingCap: number };
34	
35	export interface ScenarioResult {
36	  results: StepResult[];
37	}
38	
39	const PROCESSING_FEE = 5;
40	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
41	
42	const percentOf = (amount: number, percent: number): number =>
43	  (amount * percent) / 100;
44	
45	// MHPCO always rounds in its own favour: money it receives rounds up,
46	// money it pays out rounds down.
47	const roundIncomingInMHPCOsFavour = Math.ceil;
48	const roundOutgoingInMHPCOsFavour = Math.floor;
49	
50	const sumOf = <T>(values: T[], amountOf: (value: T) => number): number =>
51	  values.reduce((sum, value) => sum + amountOf(value), 0);
52	
53	const BASE_PREMIUM_BY_ITEM_TYPE = {
54	  sword: 100,
55	  amulet: 60,
56	  staff: 80,
57	  potion: 40,
58	  rune: 25,
59	  moonstone: 25,
60	} as const satisfies Record<string, number>;
61	
62	type InsurableItemType = keyof typeof BASE_PREMIUM_BY_ITEM_TYPE;
63	
64	const BLOCK_SIZE = 3;
65	const BLOCK_BASE_PREMIUM = 60;
66	const CURSE_SURCHARGE_PERCENT = 50;
67	const SURCHARGED_ENCHANTMENT_THRESHOLD = 5;
68	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
69	const LOYALTY_THRESHOLD_YEARS = 2;
70	const LOYALTY_DISCOUNT_PERCENT = 20;
71	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
72	
73	// Every tariff is a lookup keyed by insurable item type. The guard on the
74	// quote path has already rejected uninsurable types, so by the time any
75	// tariff is read the key is known good.
76	const tariffLookup =
77	  (tariff: Record<InsurableItemType, number>) =>
78	  (item: Item): number =>
79	    tariff[item.type as InsurableItemType];
80	
81	const basePremiumOf = tariffLookup(BASE_PREMIUM_BY_ITEM_TYPE);
82	
83	interface RiskSurcharge {
84	  appliesTo: (item: Item) => boolean;
85	  percent: number;
86	}
87	
88	const RISK_SURCHARGES: RiskSurcharge[] = [
89	  { appliesTo: (item) => item.cursed === true, percent: CURSE_SURCHARGE_PERCENT },
90	  {
91	    appliesTo: (item) =>
92	      (item.enchantment ?? 0) >= SURCHARGED_ENCHANTMENT_THRESHOLD,
93	    percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
94	  },
95	];
96	
97	const itemSurcharge = (item: Item): number =>
98	  sumOf(
99	    RISK_SURCHARGES.filter((surcharge) => surcharge.appliesTo(item)),
100	    (surcharge) => percentOf(basePremiumOf(item), surcharge.percent),
101	  );
102	
103	const policySurcharges = (items: Item[]): number => sumOf(items, itemSurcharge);
104	
105	const groupByType = (items: Item[]): Item[][] => [
106	  ...items
107	    .reduce(
108	      (groups, item) =>
109	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
110	      new Map<string, Item[]>(),
111	    )
112	    .values(),
113	];
114	
115	const basePremiumOfGroup = (group: Item[]): number =>
116	  group.length === BLOCK_SIZE
117	    ? BLOCK_BASE_PREMIUM
118	    : sumOf(group, basePremiumOf);
119	
120	const policyBasePremium = (items: Item[]): number =>
121	  sumOf(groupByType(items), basePremiumOfGroup);
122	
123	interface QuoteContext {
124	  customer: Customer;
125	  previousQuotes: number;
126	}
127	
128	const isLoyal = ({ customer }: QuoteContext): boolean =>
129	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
130	
131	const isFollowUpContract = ({ previousQuotes }: QuoteContext): boolean =>
132	  previousQuotes > 0;
133	
134	interface PolicyAdjustment {
135	  appliesTo: (context: QuoteContext) => boolean;
136	  percent: number;
137	}
138	
139	const POLICY_ADJUSTMENTS: PolicyAdjustment[] = [
140	  { appliesTo: () => true, percent: FIRST_INSURANCE_SURCHARGE_PERCENT },
141	  { appliesTo: isLoyal, percent: -LOYALTY_DISCOUNT_PERCENT },
142	  { appliesTo: isFollowUpContract, percent: -FOLLOW_UP_DISCOUNT_PERCENT },
143	];
144	
145	const policyAdjustments = (policyBase: number, context: QuoteContext): number =>
146	  sumOf(
147	    POLICY_ADJUSTMENTS.filter((adjustment) => adjustment.appliesTo(context)),
148	    (adjustment) => percentOf(policyBase, adjustment.percent),
149	  );
150	
151	const isInsurableType = (type: string): type is InsurableItemType =>
152	  type in BASE_PREMIUM_BY_ITEM_TYPE;
153	
154	// The MHPCO's price list is closed: an item it has no tariff for cannot be
155	// quoted at all, so the whole quote is rejected.
156	const rejectUninsurableItems = (items: Item[]): void => {
157	  for (const { type } of items) {
158	    if (!isInsurableType(type)) {
159	      throw new Error(`the MHPCO does not insure items of type ${type}`);
160	    }
161	  }
162	};
163	
164	const quotePremium = (items: Item[], context: QuoteContext): number => {
165	  rejectUninsurableItems(items);
166	  const policyBase = policyBasePremium(items);
167	  const premiumBeforeFee =
168	    policyBase + policySurcharges(items) + policyAdjustments(policyBase, context);
169	  return roundIncomingInMHPCOsFavour(premiumBeforeFee + PROCESSING_FEE);
170	};
171	
172	const INSURANCE_VALUE_BY_ITEM_TYPE = {
173	  sword: 1000,
174	  amulet: 600,
175	  staff: 800,
176	  potion: 400,
177	  rune: 250,
178	  moonstone: 250,
179	} as const satisfies Record<InsurableItemType, number>;
180	
181	const DEDUCTIBLE_PER_DAMAGE = 100;
182	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
183	
184	const insuranceValueOf = tariffLookup(INSURANCE_VALUE_BY_ITEM_TYPE);
185	
186	// Unlike the base premium, the cap does not group items by type: every item
187	// contributes its full insurance value, so two swords insure for 2 x 1000 G.
188	// Block discounts are a premium concept only.
189	const policyCapOf = (items: Item[]): number =>
190	  CAP_MULTIPLE_OF_INSURANCE_SUM * sumOf(items, insuranceValueOf);
191	
192	const HALVING_ENCHANTMENT_THRESHOLD = 8;
193	const HALVED_REIMBURSEMENT_PERCENT = 50;
194	
195	const FULL_REIMBURSEMENT_PERCENT = 100;
196	
197	const reimbursesAtHalf = (item: Item | undefined): boolean =>
198	  (item?.enchantment ?? 0) >= HALVING_ENCHANTMENT_THRESHOLD;
199	
200	const reimbursementPercentFor = (item: Item | undefined): number =>
201	  reimbursesAtHalf(item)
202	    ? HALVED_REIMBURSEMENT_PERCENT
203	    : FULL_REIMBURSEMENT_PERCENT;
204	
205	// Matches by type only, so several damage entries of one type all resolve to
206	// the same insured item. Safe because rejectDamagesNotBackedByInsuredItems has
207	// already guaranteed there are at least as many insured items of the type as
208	// damage entries, and items of a type are interchangeable for reimbursement.
209	const insuredItemFor = (damage: Damage, insured: Item[]): Item | undefined =>
210	  insured.find(({ type }) => type === damage.itemType);
211	
212	// Each damage entry carries its own deductible, so a two-sword incident is
213	// docked 100 G twice.
214	const reimbursementFor = (damage: Damage, insured: Item[]): number =>
215	  percentOf(
216	    damage.amount,
217	    reimbursementPercentFor(insuredItemFor(damage, insured)),
218	  ) - DEDUCTIBLE_PER_DAMAGE;
219	
220	const policyOf = (step: Extract<Step, { op: "claim" }>, steps: Step[]) => {
221	  const policy = steps[step.policy];
222	  if (policy?.op !== "quote") throw new Error("claim references no policy");
223	  return policy;
224	};
225	
226	// A claim consumes part of its policy's cap, so each policy carries a
227	// remaining cap that later claims against the same policy draw down.
228	type RemainingCapByPolicy = ReadonlyMap<number, number>;
229	
230	const countByType = <T>(values: T[], typeOf: (value: T) => string) =>
231	  values.reduce((counts, value) => {
232	    const type = typeOf(value);
233	    return counts.set(type, (counts.get(type) ?? 0) + 1);
234	  }, new Map<string, number>());
235	
236	// Every damage entry must be backed by its own insured item, which settles
237	// three spec rules at once: an item the policy never covered has nothing to
238	// back it; a second damage to a singly-insured item has nothing left to back
239	// it; and an item of an unknown type can never be insured at all, because the
240	// quote guard rejects the policy before it is written. Any of the three
241	// rejects the whole claim rather than honouring it in part.
242	const rejectDamagesNotBackedByInsuredItems = (
243	  damages: Damage[],
244	  insured: Item[],
245	): void => {
246	  const insuredCounts = countByType(insured, ({ type }) => type);
247	  for (const [itemType, damaged] of countByType(
248	    damages,
249	    ({ itemType }) => itemType,
250	  )) {
251	    const covered = insuredCounts.get(itemType) ?? 0;
252	    if (damaged > covered) {
253	      throw new Error(
254	        covered === 0
255	          ? `claim reports damage to ${itemType}, which the policy does not cover`
256	          : `claim reports more ${itemType} damages than the policy covers`,
257	      );
258	    }
259	  }
260	};
261	
262	// A damage is a loss, never a gain: the MHPCO does not accept claims that
263	// would have it collect money from the customer.
264	const rejectNegativeDamageAmounts = (damages: Damage[]): void => {
265	  for (const { itemType, amount } of damages) {
266	    if (amount < 0) {
267	      throw new Error(
268	        `claim reports a negative damage amount of ${amount} for ${itemType}`,
269	      );
270	    }
271	  }
272	};
273	
274	// Settling a claim is a state transition: it reports what the customer is
275	// paid and what the policy has left. The caller owns the running state.
276	const settleClaim = (
277	  step: Extract<Step, { op: "claim" }>,
278	  steps: Step[],
279	  remainingCaps: RemainingCapByPolicy,
280	): { payout: number; remainingCap: number } => {
281	  const insured = policyOf(step, steps).items;
282	  rejectDamagesNotBackedByInsuredItems(step.incident.damages, insured);
283	  rejectNegativeDamageAmounts(step.incident.damages);
284	  const desiredPayout = roundOutgoingInMHPCOsFavour(
285	    sumOf(step.incident.damages, (damage) => reimbursementFor(damage, insured)),
286	  );
287	  const capBeforeClaim =
288	    remainingCaps.get(step.policy) ?? policyCapOf(insured);
289	  const payout = Math.min(desiredPayout, capBeforeClaim);
290	  return { payout, remainingCap: capBeforeClaim - payout };
291	};
292	
293	const countQuotesBefore = (steps: Step[], index: number): number =>
294	  steps.slice(0, index).filter((step) => step.op === "quote").length;
295	
296	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
297	  // The one place that owns the running cap state: settleClaim reports each
298	  // policy's new remaining cap, and the write back happens here, in plain sight.
299	  const remainingCaps = new Map<number, number>();
300	  return {
301	    results: steps.map((step, index) => {
302	      if (step.op === "quote") {
303	        const context = {
304	          customer,
305	          previousQuotes: countQuotesBefore(steps, index),
306	        };
307	        return { premium: quotePremium(step.items, context) };
308	      }
309	      const result = settleClaim(step, steps, remainingCaps);
310	      remainingCaps.set(step.policy, result.remainingCap);
311	      return result;
312	    }),
313	  };
314	};
